const axios = require("axios");

async function processYoutubeDownload(youtubeUrl) {
  try {
    const initialResponse = await axios.post(
      "https://api-v1.saveto.ai/api/app/tools/youtube_parse",
      {
        url: youtubeUrl,
        quality: "360p"
      },
      {
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json, text/plain, */*",
          "fp": "5ffe58201cb199bf8580c8c7d4a9ab21",
          "fp1": "PKIXDBDcfx/WsUDS7e57qKTbO/T95SAka6F9//f1l8DAWn7640Rt838+9bxXY00a",
          "x-guide": "KassIt4svsjkXYa9GiW/gLBDPk/qe7iUJSnyxuV6AOl4h2X7lYlxE33zeLPj5jhh2irmbAR/Gw76Lj7N0sf3CI+jAzszLYG/OrJAlrkKFyJv88y6UnhrlD02k19cNWPVqh0OOlpLj3tLLepS91f8fVhUgthOm54J7la/O+o38/0=",
          "theme-version": "83EmcUoQTUv50LhNx0VrdcK8rcGexcP35FcZDcpgWsAXEyO4xqL5shCY6sFIWB2Q",
          "X-code": "1786584033830"
        }
      }
    );

    const progressId = initialResponse.data.data.progress_id;

    const taskResponse = await axios.post(
      "https://api-v1.saveto.ai/api/app/tools/youtube_task",
      {
        url: youtubeUrl,
        quality: "360p"
      },
      {
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json, text/plain, */*",
          "fp": "5ffe58201cb199bf8580c8c7d4a9ab21",
          "fp1": "NOkMWFwb1AjxwiHFLTKNfghyKa7vZMh4nhbcd10US47OXR2yGFK9QlEq0SCNfE5O",
          "x-guide": "CtPAPiNYb3RhcRXi84ljMpt5xh6iinkjRPlres6fIOWt3+TGgsQJYCWnjo5IgYk8esSDEgMmUno4keQI9W8XBXDB6RS8lGn115xbGsHQVTN9gkJT4oXSKWUHOSfVI+7qhatkTnOimwW+0kiWcxKJJgk17/gMqLaJMhg5rGzqe18=",
          "theme-version": "83EmcUoQTUv50LhNx0VrdcK8rcGexcP35FcZDcpgWsAXEyO4xqL5shCY6sFIWB2Q",
          "X-code": "1786584048052"
        }
      }
    );

    const progressResponse = await axios.post(
      "https://api-v1.saveto.ai/api/app/tools/youtube_progress",
      {
        progress_id: taskResponse.data.data.progress_id
