          "theme-version": "83EmcUoQTUv50LhNx0VrdcK8rcGexcP35FcZDcpgWsAXEyO4xqL5shCY6sFIWB2Q",
          "X-code": "1786584061047"
        }
      }
    );

    return progressResponse.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

